<script setup>import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {useAuthStore} from '../stores/auth';const collapsed=ref(false),auth=useAuthStore(),route=useRoute();const manager=computed(()=>auth.user?.role==='LAB_ADMIN'),admin=computed(()=>auth.user?.role==='SYSTEM_ADMIN'),reportsAccess=computed(()=>manager.value||admin.value);const roleName={USER:'普通用户',LAB_ADMIN:'实验室管理员',SYSTEM_ADMIN:'系统管理员'};</script>
<template><el-container class="shell"><el-aside :width="collapsed?'72px':'230px'" class="side"><div class="logo"><span class="logo-icon"><OfficeBuilding/></span><b v-show="!collapsed">LabSpace</b></div><el-menu router :default-active="route.path" :collapse="collapsed"><el-menu-item index="/dashboard"><el-icon><DataAnalysis/></el-icon><template #title>{{auth.user?.role==='USER'?'实验室指南':'数据概览'}}</template></el-menu-item><el-menu-item index="/labs"><el-icon><School/></el-icon><template #title>实验室管理</template></el-menu-item><el-menu-item v-if="!admin" index="/reservations"><el-icon><Calendar/></el-icon><template #title>{{manager?'我负责的预约':'我的预约'}}</template></el-menu-item><el-menu-item v-if="auth.user?.role==='USER'" index="/ai-assistant"><el-icon><ChatDotRound/></el-icon><template #title>AI实验室助手</template></el-menu-item><el-menu-item index="/devices"><el-icon><Monitor/></el-icon><template #title>设备台账</template></el-menu-item><el-menu-item index="/repairs"><el-icon><Tools/></el-icon><template #title>{{manager?'维修处理':admin?'全局维修管理':'故障报修'}}</template></el-menu-item><el-menu-item v-if="reportsAccess" index="/reports"><el-icon><DataAnalysis/></el-icon><template #title>统计报表</template></el-menu-item><el-menu-item v-if="admin" index="/users"><el-icon><UserFilled/></el-icon><template #title>用户与权限管理</template></el-menu-item></el-menu><div class="side-foot" v-show="!collapsed">实验资源管理平台<br/><small>Version 1.0.0</small></div></el-aside><el-container><el-header><div class="collapse" @click="collapsed=!collapsed"><Fold v-if="!collapsed"/><Expand v-else/></div><div class="crumb">首页 / <b>{{route.path==='/dashboard'&&auth.user?.role==='USER'?'实验室指南':route.meta.title||'工作台'}}</b></div><div class="profile"><el-avatar>{{auth.user?.realName?.[0]}}</el-avatar><div><b>{{auth.user?.realName}}</b><span>{{roleName[auth.user?.role]}}</span></div><el-dropdown><MoreFilled class="more"/><template #dropdown><el-dropdown-menu><el-dropdown-item @click="auth.logout">退出登录</el-dropdown-item></el-dropdown-